@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_self_tail_call_shapes(run, workdir, case):
    """CATCHES: a tail call rewritten where the reference keeps recursion (or the reverse),
    a missing or differently worded note, wrong parallel rebinding, or wrong values."""
    S.check(run, workdir, case, __file__)
